"use client";

import { TrendingUp, AlertTriangle } from "lucide-react";

export default function LeaderboardRuangan({ data }: { data: any[] }) {
  // 1. Logika menghitung akumulasi HAIs per ruangan
  const statsMap = (data || []).reduce((acc: any, curr) => {
    const ruangan = curr.master_ruangan?.nama_ruangan || "Tanpa Nama";
    
    // Pastikan semua nilai dikonversi ke angka
    const totalHais = 
      Number(curr.isk || 0) + 
      Number(curr.iad || 0) + 
      Number(curr.vap || 0) + 
      Number(curr.hap || 0);

    // Hapus baris "if (totalHais > 0)" jika Ayah ingin ruangan tetap muncul meski nol,
    // atau biarkan jika hanya ingin ruangan dengan kasus saja yang tampil.
    if (totalHais > 0) {
      if (!acc[ruangan]) {
        acc[ruangan] = 0;
      }
      acc[ruangan] += totalHais;
    }
    return acc;
  }, {});

  // 2. Mengubah objek menjadi array, mengurutkan, dan mengambil Top 5
  const sortedStats = Object.entries(statsMap)
    .map(([name, total]) => ({ name, total: total as number }))
    .sort((a, b) => b.total - a.total)
    .slice(0, 5);

  // Nilai tertinggi untuk kalkulasi lebar progress bar
  const maxCases = sortedStats.length > 0 ? sortedStats[0].total : 1;

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-100 p-8 shadow-sm h-full font-sans">
      {/* Header Leaderboard */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h3 className="text-sm font-black text-slate-800 uppercase italic tracking-tighter">
            Top Ruangan Bermasalah
          </h3>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
            Ranking Temuan HAIs
          </p>
        </div>
        <div className="w-10 h-10 bg-red-50 text-red-500 rounded-xl flex items-center justify-center">
          <TrendingUp size={20} />
        </div>
      </div>

      {/* List Ruangan */}
      <div className="space-y-6">
        {sortedStats.length === 0 ? (
          <div className="py-10 text-center">
            <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest italic">
              Alhamdulillah, Belum Ada Kasus HAIs
            </p>
          </div>
        ) : (
          sortedStats.map((item, idx) => (
            <div key={idx} className="group">
              <div className="flex justify-between items-end mb-2">
                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-300 w-4">
                    0{idx + 1}
                  </span>
                  <span className="text-xs font-bold text-slate-700 uppercase tracking-tight truncate max-w-[150px]">
                    {item.name}
                  </span>
                </div>
                <span className="text-[11px] font-black text-red-600">
                  {item.total} <small className="text-[9px] opacity-50 uppercase">Kasus</small>
                </span>
              </div>
              
              {/* Progress Bar Visual */}
              <div className="relative w-full h-2 bg-slate-50 rounded-full overflow-hidden">
                <div 
                  className="absolute top-0 left-0 h-full bg-red-500 rounded-full transition-all duration-1000 ease-out"
                  style={{ 
                    width: `${(item.total / maxCases) * 100}%`,
                    opacity: 1 - (idx * 0.15) // Memberikan efek gradasi warna per peringkat
                  }}
                />
              </div>
            </div>
          ))
        )}
      </div>

      {/* Footer Audit Alert */}
      {sortedStats.length > 0 && (
        <div className="mt-10 pt-6 border-t border-slate-50">
          <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex items-start gap-3">
            <AlertTriangle size={16} className="text-amber-600 shrink-0 mt-0.5" />
            <div>
              <p className="text-[10px] font-black text-amber-700 uppercase leading-tight tracking-tight">
                Rekomendasi Tindakan:
              </p>
              <p className="text-[10px] font-bold text-amber-600/80 mt-1 leading-relaxed">
                Unit <span className="underline">{sortedStats[0].name}</span> memiliki angka HAIs tertinggi. Jadwalkan audit ruangan dan evaluasi kepatuhan hand hygiene segera.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}